draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 30, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 30);
  ctx.lineTo(W/2, H/2 - 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 20, H/2 - 40);
  ctx.lineTo(W/2 - 40, H/2 - 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 20, H/2 - 40);
  ctx.lineTo(W/2 + 40, H/2 - 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 - 40, H/2 + 20, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 40, H/2 + 20, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2, H/2 + 60 + 20 * Math.sin(t));
  ctx.stroke();
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Enough', W/2, H/2 + 100);
  ctx.restore();
}
